import React from 'react';

const ProductionTimeline = ({ milestones, tasks }) => {
  // Timeline data
  const phases = [
    { id: 'pre-production', name: 'PRE-PRODUCTION', order: 0 },
    { id: 'production', name: 'PRODUCTION', order: 1 },
    { id: 'post-production', name: 'POST-PRODUCTION', order: 2 }
  ];
  
  // Calculate completion for each milestone
  const calculateMilestoneProgress = () => {
    const progress = {};
    
    phases.forEach(phase => {
      const milestoneName = phase.name.charAt(0) + phase.name.slice(1).toLowerCase();
      const milestoneTasks = tasks.filter(task => task.milestone === milestoneName);
      const totalTasks = milestoneTasks.length;
      const completedTasks = milestoneTasks.filter(task => task.completed).length;
      
      progress[phase.id] = totalTasks > 0 ? (completedTasks / totalTasks) * 100 : 0;
    });
    
    return progress;
  };
  
  // Determine active phase
  const getActivePhase = () => {
    const activeMilestone = milestones.find(m => m.active);
    if (!activeMilestone) return phases[0].id;
    
    const milestoneName = activeMilestone.name.toLowerCase().replace('-', '');
    const matchingPhase = phases.find(p => p.id === milestoneName);
    return matchingPhase ? matchingPhase.id : phases[0].id;
  };
  
  // Calculate timeline position based on completed tasks
  const calculatePosition = () => {
    const progress = calculateMilestoneProgress();
    const activePhase = getActivePhase();
    const activePhaseIndex = phases.findIndex(p => p.id === activePhase);
    
    // Base position for the start of current phase
    const basePosition = (activePhaseIndex * 100) / phases.length;
    
    // Progress within the current phase
    const phaseWidth = 100 / phases.length;
    const phaseProgress = (progress[activePhase] * phaseWidth) / 100;
    
    return basePosition + phaseProgress;
  };
  
  const currentPosition = calculatePosition();
  
  return (
    <div className="w-full mt-8 mb-12 relative">
      {/* Dark background for entire timeline area */}
      <div className="w-full bg-gray-900 h-96 rounded-lg overflow-hidden relative">
        {/* Phase sections */}
        <div className="flex flex-row h-full">
          {phases.map((phase, index) => {
            // Determine if this phase is the active one
            const activePhase = getActivePhase();
            const isActive = phase.id === activePhase;
            
            return (
              <div 
                key={phase.id} 
                className="flex-1 flex flex-col justify-between border-r border-gray-800 relative p-6"
                style={{ 
                  backgroundColor: isActive ? 'rgba(40, 20, 30, 0.5)' : 'rgba(30, 20, 30, 0.3)',
                }}
              >
                <div className="text-pink-300 font-bold text-2xl tracking-wider">
                  {phase.name}
                </div>
                
                {/* Display task completion percentage for this phase */}
                <div className="text-white text-lg mt-4">
                  {Math.round(calculateMilestoneProgress()[phase.id])}% Complete
                </div>
                
                {/* Phase content would go here */}
                <div className="flex-grow">
                  {/* Content specific to each phase could be rendered here */}
                </div>
              </div>
            );
          })}
        </div>
        
        {/* Timeline bar */}
        <div className="absolute bottom-0 left-0 right-0 h-12 flex items-center px-4">
          <div className="w-full h-2 bg-gray-800 rounded-full overflow-hidden">
            <div 
              className="h-full bg-gradient-to-r from-pink-500 to-pink-300"
              style={{ width: `${currentPosition}%` }}
            />
          </div>
        </div>
        
        {/* "You are here" indicator */}
        <div 
          className="absolute bottom-6 flex flex-col items-center"
          style={{ 
            left: `${currentPosition}%`, 
            transform: 'translateX(-50%)'
          }}
        >
          <div className="text-white mb-2 font-bold">YOU ARE HERE</div>
          <div className="w-8 h-8 rounded-full bg-white border-4 border-pink-500 z-10" />
          {/* Line connecting to timeline */}
          <div className="h-4 w-px bg-white" />
        </div>
      </div>
    </div>
  );
};

export default ProductionTimeline;
